Here is a simple C++ function that takes a reference to a std::string containing markdown formatted text and returns a std::string containing html formatted text:

```cpp
#include <string>
#include <sstream>
#include <iostream>

std::string formatHtml(const std::string& text) {
    std::istringstream iss(text);
    std::string html;
    while (iss >> html) {
        html += "<br />";
    }
    html.erase(html.end() - html.size(), html.end());
    return html;
}
```

